<?php
namespace App\Services;use App\Models\{ApLoadSample,FeedbackResponse,Measurement};use Carbon\CarbonInterface;
class FeedbackCorrelationService{
 public function correlate(FeedbackResponse $feedback,int $windowMinutes=30):array{$from=$feedback->experienced_at->copy()->subMinutes($windowMinutes);$to=$feedback->experienced_at->copy()->addMinutes($windowMinutes);$measurementQuery=Measurement::query()->where('is_simulated',false)->whereBetween('captured_at',[$from,$to])->whereHas('point.survey',function($q)use($feedback){$q->where('floor_id',$feedback->floor_id);if($feedback->survey_area_id)$q->where('survey_area_id',$feedback->survey_area_id);});$measurements=$measurementQuery->get();$apSamples=ApLoadSample::query()->whereBetween('sampled_at',[$from,$to])->whereHas('accessPoint',function($q)use($feedback){$q->where('floor_id',$feedback->floor_id);if($feedback->survey_area_id)$q->where('survey_area_id',$feedback->survey_area_id);})->get();$created=[];foreach($measurements as $m){$diff=abs($m->captured_at->diffInMinutes($feedback->experienced_at,false));$strength=$this->strength($diff,$feedback->survey_area_id!==null);$evidence=['rssi_dbm'=>$m->rssi_dbm,'download_mbps'=>$m->download_mbps,'latency_ms'=>$m->latency_ms,'packet_loss_percent'=>$m->packet_loss_percent,'problem_type'=>$feedback->problem_type];$created[]=$feedback->correlations()->updateOrCreate(['measurement_id'=>$m->id,'ap_load_sample_id'=>null],['strength'=>$strength,'time_difference_minutes'=>$diff,'location_match'=>$feedback->survey_area_id?'survey_area':'floor','evidence'=>$evidence,'calculation_version'=>'1.0']);}foreach($apSamples as $s){$diff=abs($s->sampled_at->diffInMinutes($feedback->experienced_at,false));$strength=$this->strength($diff,$feedback->survey_area_id!==null);$created[]=$feedback->correlations()->updateOrCreate(['measurement_id'=>null,'ap_load_sample_id'=>$s->id],['strength'=>$strength,'time_difference_minutes'=>$diff,'location_match'=>$feedback->survey_area_id?'survey_area':'floor','evidence'=>['connected_clients'=>$s->connected_clients,'channel_utilisation_percent'=>$s->channel_utilisation_percent,'latency_ms'=>$s->latency_ms,'packet_loss_percent'=>$s->packet_loss_percent,'problem_type'=>$feedback->problem_type],'calculation_version'=>'1.0']);}return['measurement_matches'=>$measurements->count(),'ap_load_matches'=>$apSamples->count(),'total_correlations'=>count($created),'overall_strength'=>$this->overall($created),'limitations'=>count($created)?[]:['No technical measurements were found in the selected location and ±'.$windowMinutes.' minute window.']];}
 private function strength(float $minutes,bool $exactArea):string{if($exactArea&&$minutes<=15)return'strong';if($minutes<=30)return'moderate';return'weak';}private function overall(array $rows):string{if(!$rows)return'insufficient_data';$values=collect($rows)->pluck('strength');if($values->contains('strong'))return'strong';if($values->contains('moderate'))return'moderate';return'weak';}}
